Q: How to mass edit XML? A: <p>I realize this is not really sophisticated, but if, and <strong>only if</strong> your XML is formatted exactly as you've shown me (with the tabs and newlines <em>exactly</em> like that), then you can just use the script I just made you:</p>
<pre class="lang-py prettyprint-override"><code>import os
from sys import exit

file_to_fix = input(&quot;file to fix: &quot;)

if not os.path.exists(file_to_fix):
    print(&quot;File doesn't exist.&quot;)
    exit(1)

if not os.path.isfile(file_to_fix):
    print(&quot;Path is not file.&quot;)
    exit(1)

dry_run = None
while dry_run == None:
    dry_run_read = input(&quot;Dry run (y/n)? &quot;)
    if dry_run_read.lower() == &quot;y&quot;:
        dry_run = True
    else:
        if dry_run_read.lower() == &quot;n&quot;:
            dry_run = False
        else:
            print(&quot;Invalid input, either y or n.&quot;)

file = open(file_to_fix, &quot;r&quot;)
file_contents = file.read()

lines = file_contents.split(&quot;\n&quot;)

for index, line in enumerate(lines):
    if line.startswith(&quot;    &quot;):
        if line[len(&quot;    &quot;):] == &quot;&lt;text&gt;&quot;:
            if dry_run:
                print(&quot;Would've fixed line &quot; + str(index + 1) + &quot;.&quot;)
            else:
                print(&quot;Fixed line &quot; + str(index + 1) + &quot;.&quot;)
                lines[index] = &quot;    &lt;comment&gt;&quot;

file.close()

if not dry_run:
    file = open(file_to_fix, &quot;w&quot;)
    print(&quot;Writing file...&quot;)
    file.write(&quot;\n&quot;.join(lines))
    file.close()
    print(&quot;Wrote file.&quot;)
    print(&quot;Fixed file '&quot; + file_to_fix + &quot;'.&quot;)
else:
    print(&quot;Would've written file.&quot;)
    print(&quot;would've fixed file '&quot; + file_to_fix + &quot;'.&quot;)
</code></pre>
